HW = {
 '4-6': ('Halloween Homework · 4–6', ['Карточки: смотри, слушай, повторяй', 'Послушай и выбери картинку', 'Послушай слово и найди картинку', 'Послушай слово: это она? (привидение ✓ / ✗)', '🎤 Назови, что видишь на картинке']),
 '7b': ('Halloween Homework · 7–9 · beginners', ['Карточки со звуком', '🎤 Повтори слова', 'Послушай и выбери картинку', 'Послушай слово и найди картинку', 'Соедини слово и картинку', '🎤 Назови, что видишь на картинке']),
 '7c': ('Halloween Homework · 7–9 · advanced', ['Карточки со звуком', 'Соедини слово и картинку', 'Собери слово из букв', 'There is / There are', 'in / on / under', 'Верно / неверно по картинке', '🎤 Расскажи про комнату']),
 '10b': ('Halloween Homework · 10–12 · beginners', ['Карточки со звуком', '🎤 Повтори слова', 'Послушай и выбери картинку', 'Соедини слово и картинку', 'Собери слово из букв', '🎤 Назови, что видишь на картинке']),
 '10c': ('Halloween Homework · 10–12 · advanced', ['Карточки (6 слов)', 'Послушай и выбери картинку', 'Соедини слово и картинку', 'Прочитай и выбери, кто это', 'Собери слово из букв', 'Послушай и напиши', 'Текст «The Golden Pumpkin» с пропусками', '🎤 Расскажи, как ты празднуешь Хэллоуин']),
 '13b': ('Halloween Homework · 13+ · beginners', ['Карточки со звуком', '🎤 Повтори слова', 'Послушай и выбери картинку', 'Соедини слово и картинку', 'Собери слово из букв', '🎤 Назови, что видишь на картинке']),
 '13c': ('Halloween Homework · 13+ · advanced', ['Карточки с переводом', 'Соедини слово и определение', 'Собери слово из букв', 'Послушай и напиши', 'Текст о Самайне с пропусками', 'True / False по тексту', '🎤 Расскажи, как ты празднуешь Хэллоуин']),
}
def hw_block(key):
    f, items = HW[key]
    li = ''.join(f'<li>{x}</li>' for x in items)
    return (f'<div class="voc"><b>🏠 Домашнее задание</b> — материал <b>«{f}»</b> на платформе: «Материалы» → «Задать ДЗ» → ученик → отметить. Только слова урока, 10–15 минут. '
            f'Задания:<ol style="margin:6px 0 0 22px">{li}</ol>'
            f'<div style="color:#777;font-size:13px;margin-top:4px">Устные задания ученик записывает голосом — их вы слушаете и оцениваете в «Проверке ДЗ».</div></div>')
def add(plan, key):
    return plan.replace('</body>', hw_block(key) + '</body>') if '</body>' in plan else plan + hw_block(key)
